// PATCH(greptile-g3): inspect preview paths without creating config directories.
func previewKlaviyoAccountChange(cmd *cobra.Command, flags *rootFlags, name, action string, selectAccount bool) error {
	root, err := config.RootDir()
	if err != nil {
		return fmt.Errorf("resolving config dir: %w", err)
	}
	root = filepath.Join(root, "klaviyo-pp-cli")
	_, err = os.Stat(filepath.Join(root, "accounts", name+".toml"))
	exists := err == nil
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	if action != "add" && !exists {
		return fmt.Errorf("account %q not found", name)
	}
	preview := map[string]any{"dry_run": true, "action": action, "account": name}
	var detail string
	switch action {
	case "add":
		preview["replace_account"] = exists
		preview["select_account"] = selectAccount
		detail = fmt.Sprintf("replace account: %t, select account: %t", exists, selectAccount)
	case "use":
		preview["select_account"] = selectAccount
		detail = fmt.Sprintf("select account: %t", selectAccount)
	case "delete":
		data, err := os.ReadFile(filepath.Join(root, "active-account"))
		if err != nil && !os.IsNotExist(err) {
			return err
		}
		clearsSelection := strings.TrimSpace(string(data)) == name
		preview["clears_selection"] = clearsSelection
		detail = fmt.Sprintf("clear selection: %t", clearsSelection)
	}
	if flags.asJSON {
		return flags.printJSON(cmd, preview)
	}
	_, err = fmt.Fprintf(cmd.OutOrStdout(), "dry run: would %s account %q (%s)\n", action, name, detail)
	return err
}

func loadEffectiveKlaviyoConfig(configPath string) (*config.Config, error) {
	path, err := effectiveKlaviyoConfigPath(configPath)
	if err != nil {
		return nil, err
	}
	return config.Load(path)
}

func effectiveKlaviyoConfigPath(configPath string) (string, error) {
	if strings.TrimSpace(configPath) != "" || os.Getenv("KLAVIYO_CONFIG") != "" {
		return configPath, nil
	}
	name, err := currentKlaviyoAccountName()
	if err != nil || name == "" {
		return "", err
	}
	path, err := klaviyoAccountConfigPath(name)
	if err != nil {
		return "", err
	}
	if _, err := os.Stat(path); err != nil {
		if os.IsNotExist(err) {
			return "", fmt.Errorf("selected account %q not found", name)
		}
		return "", err
	}
	return path, nil
}

func listKlaviyoAccountInfos() ([]klaviyoAccountInfo, error) {
	names, err := listKlaviyoAccountNames()
	if err != nil {
		return nil, err
	}
	infos := make([]klaviyoAccountInfo, 0, len(names))
	for _, name := range names {
		info, err := klaviyoAccountInfoForName(name)
		if err != nil {
			return nil, err
		}
		infos = append(infos, info)
	}
	return infos, nil
}

func klaviyoAccountInfoForName(name string) (klaviyoAccountInfo, error) {
	if err := validateKlaviyoAccountName(name); err != nil {
		return klaviyoAccountInfo{}, err
	}
	path, err := klaviyoAccountConfigPath(name)
	if err != nil {
		return klaviyoAccountInfo{}, err
	}
	if _, err := os.Stat(path); err != nil {
		if os.IsNotExist(err) {
			return klaviyoAccountInfo{}, fmt.Errorf("account %q not found", name)
		}
		return klaviyoAccountInfo{}, err
	}
	cfg, err := config.Load(path)
	if err != nil {
		return klaviyoAccountInfo{}, configErr(err)
	}
	current, err := currentKlaviyoAccountName()
	if err != nil {
		return klaviyoAccountInfo{}, err
	}
	return klaviyoAccountInfo{
		Name:          name,
		Selected:      current == name,
		ConfigPath:    path,
		BaseURL:       cfg.BaseURL,
		Authenticated: cfg.AuthHeader() != "",
	}, nil
}

func listKlaviyoAccountNames() ([]string, error) {
	dir, err := klaviyoAccountsDir()
	if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(entries))
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name, ok := strings.CutSuffix(entry.Name(), ".toml")
		if !ok {
			continue
		}
		names = append(names, name)
	}
	sort.Strings(names)
	return names, nil
}

func currentKlaviyoAccountName() (string, error) {
	path, err := klaviyoActiveAccountPath()
	if err != nil {
		return "", err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return "", nil
		}
		return "", err
	}
	return strings.TrimSpace(string(data)), nil
}

func writeCurrentKlaviyoAccountName(name string) error {
	if err := validateKlaviyoAccountName(name); err != nil {
		return err
	}
	path, err := klaviyoActiveAccountPath()
	if err != nil {
		return err
	}
	return os.WriteFile(path, []byte(name+"\n"), 0o600)
}

func validateKlaviyoAccountName(name string) error {
	if strings.TrimSpace(name) == "" {
		return fmt.Errorf("account name is required")
	}
	if strings.ContainsAny(name, `/\: `) {
		return fmt.Errorf("account name %q contains reserved characters", name)
	}
	return nil
}

func klaviyoAccountConfigPath(name string) (string, error) {
	if err := validateKlaviyoAccountName(name); err != nil {
		return "", err
	}
	dir, err := klaviyoAccountsDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, name+".toml"), nil
}

func mustKlaviyoAccountConfigPath(name string) string {
	path, _ := klaviyoAccountConfigPath(name)
	return path
}

func klaviyoAccountsDir() (string, error) {
	root, err := klaviyoConfigRoot()
	if err != nil {
		return "", err
	}
	dir := filepath.Join(root, "accounts")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", fmt.Errorf("creating accounts dir: %w", err)
	}
	return dir, nil
}

func klaviyoActiveAccountPath() (string, error) {
	root, err := klaviyoConfigRoot()
	if err != nil {
		return "", err
	}
	return filepath.Join(root, "active-account"), nil
}

func mustKlaviyoActiveAccountPath() string {
	path, _ := klaviyoActiveAccountPath()
	return path
}

func klaviyoConfigRoot() (string, error) {
	dir, err := config.RootDir()
	if err != nil {
		return "", fmt.Errorf("resolving config dir: %w", err)
	}
	dir = filepath.Join(dir, "klaviyo-pp-cli")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", fmt.Errorf("creating config dir: %w", err)
	}
	return dir, nil
}
